import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"7. Deployment View","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/arc42/07-deployment-view.md","filePath":"architecture/arc42/07-deployment-view.md","lastUpdated":1780254295000}'),d={name:"architecture/arc42/07-deployment-view.md"};function l(r,e,i,n,c,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="_7-deployment-view" tabindex="-1">7. Deployment View <a class="header-anchor" href="#_7-deployment-view" aria-label="Permalink to &quot;7. Deployment View&quot;">​</a></h1><p>Soma is deployed as a desktop application (for end users) plus optional server daemons (for connectivity, onboarding, and availability).</p><h2 id="desktop-deployment" tabindex="-1">Desktop deployment <a class="header-anchor" href="#desktop-deployment" aria-label="Permalink to &quot;Desktop deployment&quot;">​</a></h2><ul><li>Soma is packaged as an Electron app (<code>desktop/soma</code>). The <code>@soma/node</code> napi addon — a cdylib that links the <code>soma-daemon</code> and <code>soma-agentd</code> library crates — is unpacked next to the app and loaded by the Electron main process at startup.</li><li>There is no separate daemon process and no Unix-socket IPC; daemon operations are plain Rust calls inside the Electron main process. The only inter-process boundary on the desktop side is the renderer ↔ main Electron IPC bridge.</li><li>Tapia is shipped inside the Soma desktop app as the <code>/practice</code> route — there is no separate Tapia Electron app.</li></ul><h2 id="server-deployment-typical" tabindex="-1">Server deployment (typical) <a class="header-anchor" href="#server-deployment-typical" aria-label="Permalink to &quot;Server deployment (typical)&quot;">​</a></h2><p>All server peers are subcommands of the single <code>somad</code> binary:</p><ul><li><code>somad relay</code>: public-facing relay nodes for NAT traversal fallback.</li><li><code>somad rendezvous</code>: public-facing rendezvous server for discovery.</li><li><code>somad bot</code>: optional always-on bot (VDF role) for caching and join-decision automation.</li><li><code>somad bff</code>: optional HTTP service for LLM-backed features.</li><li><code>somad all --config &lt;file&gt;</code>: compose multiple modes inside one process via a TOML config.</li></ul><h2 id="local-development-topologies" tabindex="-1">Local development topologies <a class="header-anchor" href="#local-development-topologies" aria-label="Permalink to &quot;Local development topologies&quot;">​</a></h2><h3 id="host-processes" tabindex="-1">Host processes <a class="header-anchor" href="#host-processes" aria-label="Permalink to &quot;Host processes&quot;">​</a></h3><ul><li>Run the desktop app directly: <code>just desktop-run-soma</code>. The embedded daemon starts inside the Electron main process — no separate daemon to launch.</li><li>Optionally run server peers on the host: <code>just backend-run-bot</code> / <code>just backend-run-relay</code> / <code>just backend-run-rendezvous</code> / <code>just backend-run-bff</code> (all dispatch to the single <code>somad</code> binary).</li></ul><h3 id="docker-compose" tabindex="-1">Docker Compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to &quot;Docker Compose&quot;">​</a></h3><ul><li>Compose bundles live under <code>compose/</code> and are aggregated by <code>compose.yml</code>.</li><li>The root <code>justfile</code> has <code>just compose-up</code> / <code>just compose-logs</code> helpers.</li></ul><h3 id="kubernetes-helm" tabindex="-1">Kubernetes / Helm <a class="header-anchor" href="#kubernetes-helm" aria-label="Permalink to &quot;Kubernetes / Helm&quot;">​</a></h3><ul><li>Helm charts and manifests live under <code>deploy/</code>.</li><li>The <code>somad</code> container has health/metrics endpoints regardless of which subcommand it is run with.</li></ul>',14)])])}const u=o(d,[["render",l]]);export{h as __pageData,u as default};
